SELECT a.apply_id, a.created_time, a.audit_status, a.bot_id,
       b.bot_name, t.tenant_name, u1.user_name, u2.user_name AS audit_user_name
FROM BT_BOT_AUTH_APPLY a
LEFT JOIN bt_bot b ON a.bot_id = b.bot_id AND b.tenant_id = a.tenant_id
LEFT JOIN bt_tenant t ON t.tenant_id = a.tenant_id
LEFT JOIN bt_user u1 ON a.user_id = u1.user_id
LEFT JOIN bt_user u2 ON a.audit_user_id = u2.user_id
WHERE a.status_cd = '00A'
  AND a.tenant_id = #{query.tenantId}

  AND a.audit_status = #{query.auditStatus}


  AND a.creator_id = #{query.creatorId}


  AND b.bot_name LIKE #{query.searchContent}

ORDER BY a.created_time DESC

SELECT a.apply_id, a.created_time, a.bot_desc, a.audit_status, a.bot_id, a.tenant_id, b.bot_name, t.tenant_name, u1.user_name, u2.user_name AS audit_user_name, CASE WHEN b.data_from = '10A' THEN 'T' ELSE 'F' END AS "isBoteClaw" FROM BT_BOT_AUTH_APPLY a LEFT JOIN bt_bot b ON a.bot_id = b.bot_id AND b.tenant_id = a.tenant_id LEFT JOIN bt_tenant t ON t.tenant_id = a.tenant_id LEFT JOIN bt_user u1 ON a.user_id = u1.user_id LEFT JOIN bt_user u2 ON a.audit_user_id = u2.user_id WHERE a.status_cd = '00A'
AND a.audit_status = #{query.auditStatus}
AND b.bot_name LIKE #{query.searchContent}
ORDER BY a.created_time DESC
